irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    struct serio *port;
    irqreturn_t ret = IRQ_NONE;

    spin_lock(&i8042_lock);

    status = inb(I8042_STATUS);

    if (status & I8042_IBF) {
        data = inb(I8042_DATA);

        if (status & I8042_MUX) {
            if (i8042_mux_data(data))
                ret = IRQ_HANDLED;
        } else {
            port = i8042_get_port();
            if (port && i8042_filter(data)) {
                serio_interrupt(port, data, 0);
                ret = IRQ_HANDLED;
            }
        }

        if (status & I8042_TIMEOUT)
            i8042_handle_timeout();
        if (status & I8042_MUX_ERROR)
            i8042_handle_mux_error();
    }

    spin_unlock(&i8042_lock);

    return ret;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    struct i8042 *i8042 = dev_id;

    spin_lock(&i8042->lock);

    status = inb(I8042_STATUS);

    if (!(status & I8042_STR_OBF))
        goto out_unlock;

    data = inb(I8042_DATA);

    if (status & I8042_STB_MUX) {
        if (i8042->mux_state == I8042_MUX_IDLE) {
            i8042->mux_state = I8042_MUX_EXPECTING_ADDR;
            i8042->mux_current_address = data;
        } else if (i8042->mux_state == I8042_MUX_EXPECTING_ADDR) {
            i8042->mux_state = I8042_MUX_IDLE;
            if (data & 0x80) {
                printk(KERN_ERR "i8042: MUX timeout or error\n");
            }
        } else {
            i8042->mux_state = I8042_MUX_IDLE;
        }
        goto out_unlock;
    }

    if (i8042->mux_state != I8042_MUX_IDLE)
        goto out_unlock;

    if (status & (I8042_STB_TIMEOUT | I8042_STB_PARITY))
        goto out_unlock;

    if (i8042->data_filter(data) != 0)
        goto out_unlock;

    if (i8042->port0 && i8042->port0->write)
        i8042->port0->write(i8042->port0, data);

out_unlock:
    spin_unlock(&i8042->lock);
    return IRQ_HANDLED;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int handled = 0;

    spin_lock(&i8042_lock);

    status = inb_p(STATUS_PORT);

    if (status & OBF) {
        data = inb_p(DATA_PORT);

        if (status & (MUXERR | TIMEOUT)) {
            i8042_flush_data();
            i8042_flush_stray();
        } else {
            int port = i8042_get_port(status);
            if (port >= 0) {
                i8042_filter(port, data);
                serio_interrupt(port, data);
                handled = 1;
            }
        }
    }

    spin_unlock(&i8042_lock);

    return handled ? IRQ_HANDLED : IRQ_NONE;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int handled = 0;

    spin_lock(&i8042_lock);

    status = inb_p(PKBDAT_PORT);
    data = inb_p(PKBDAT_PORT);

    if ((status & 0x80) || i8042_data.timeout) {
        i8042_data.timeout = 0;
        spin_unlock(&i8042_lock);
        return IRQ_NONE;
    }

    if (i8042_data.mux) {
        if (i8042_data.mux_port) {
            i8042_data.mux_port->write(i8042_data.mux_port, data);
            handled = 1;
        }
    } else {
        if (i8042_data.serio)
            serio_interrupt(i8042_data.serio, data, 0);
        handled = 1;
    }

    spin_unlock(&i8042_lock);

    return handled ? IRQ_HANDLED : IRQ_NONE;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int handled = 0;

    spin_lock(&i8042_lock);

    status = inb_p(STATUS_PORT);

    if (status & OBF) {
        data = inb_p(DATA_PORT);

        if (status & (MUXERR | TIMEOUT)) {
            if (status & MUXERR)
                printk(KERN_WARNING "i8042: MUX error\n");
            if (status & TIMEOUT)
                printk(KERN_WARNING "i8042: Timeout error\n");
        } else if (status & (PORTA | PORTB)) {
            int port = (status & PORTB) ? 1 : 0;

            if (i8042_mux_present)
                i8042_mux_translate(data, port);

            if (i8042_filter(data, port))
                serio_interrupt(data, port);
            else
                handled = 1;
        }

        if (handled)
            i8042_ack();
    }

    spin_unlock(&i8042_lock);

    return handled ? IRQ_HANDLED : IRQ_NONE;
}
